<?php
require_once __DIR__.'/includes/auth.php';require_login();$s=$pdo->prepare('SELECT b.*,r.room_name,r.image FROM bookings b JOIN rooms r ON b.room_id=r.room_id WHERE b.user_id=? ORDER BY b.created_at DESC');$s->execute([current_user()['user_id']]);$bookings=$s->fetchAll();$pageTitle='My Stays | LUMIÈRE';require __DIR__.'/includes/header.php';?><section class="page-hero"><div><div class="eyebrow">A note of welcome</div><h1>Your stays.</h1></div></section><section class="content-wrap"><div class="section-heading"><div class="eyebrow">Bonjour, <?= e(current_user()['name']) ?></div><h2>Your time at LUMIÈRE.</h2></div><?php if($bookings): ?><table class="data-table"><thead><tr><th>Reference</th><th>Room</th><th>Dates</th><th>Guests</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($bookings as $b): ?><tr><td><?= e($b['booking_reference']) ?></td><td><?= e($b['room_name']) ?></td><td><?= e($b['check_in']) ?> — <?= e($b['check_out']) ?></td><td><?= (int)$b['guests'] ?></td><td>₹<?= number_format((float)$b['total_amount']) ?></td><td><span class="badge badge-<?= e($b['status']) ?>"><?= e($b['status']) ?></span></td></tr><?php endforeach; ?></tbody></table><?php else: ?><div class="center-message"><h2>Nothing planned just yet.</h2><p>Your next story can start here.</p><a class="button" href="booking.php">Plan a stay</a></div><?php endif; ?></section><?php require __DIR__.'/includes/footer.php';?>
